data.script:
var cb=CallbackURL.create();cb.baseURL='draftly-engine-echo://reply?existing=kept';
for(var key of ['__proto__','constructor','toString','café 🐼']) {
 if(cb.addParameter(key,'old')!==undefined)throw new Error('Wrong addParameter return');
 cb.addParameter(key,'Returned + café 🐼');
}
var query=cb.url.split('?')[1].split('&');
var expected=['__proto__','constructor','toString','café 🐼'];
if(query.length!==5)throw new Error('Wrong query count');
for(var name of expected){var hits=query.filter(function(item){return decodeURIComponent(item.split('=')[0])===name;});if(hits.length!==1||decodeURIComponent(hits[0].split('=')[1])!=='Returned + café 🐼')throw new Error('Wrong parameter '+name);}
if(query.indexOf('existing=kept')<0)throw new Error('Existing query lost');
editor.setText('Callback parameter keys preserved café 🐼');
